public final class DecisionRules {

    private static final String APPROVAL = "APPROVAL";
    private static final String REFUND = "REFUND";

    private static final String AUTO = "AUTO";
    private static final String MANUAL = "MANUAL";
    private static final String DENY = "DENY";

    private DecisionRules() {
    }

    public static String decide(String business, int amount, int days, boolean paid, boolean restricted) {
        validateCommon(business, amount, days);

        if (APPROVAL.equals(business)) {
            return decideApproval(amount, restricted);
        }
        return decideRefund(amount, days, paid);
    }

    private static void validateCommon(String business, int amount, int days) {
        if (amount < 0) {
            throw new IllegalArgumentException("amount must not be negative");
        }
        if (days < 0) {
            throw new IllegalArgumentException("days must not be negative");
        }
        if (business == null) {
            throw new IllegalArgumentException("business must not be null");
        }
        if (!APPROVAL.equals(business) && !REFUND.equals(business)) {
            throw new IllegalArgumentException("business must be exactly APPROVAL or REFUND");
        }
    }

    private static String decideApproval(int amount, boolean restricted) {
        if (restricted) {
            return DENY;
        }
        if (amount <= 1000) {
            return AUTO;
        }
        return MANUAL;
    }

    private static String decideRefund(int amount, int days, boolean paid) {
        if (!paid) {
            return DENY;
        }
        if (days > 7) {
            return DENY;
        }
        return AUTO;
    }
}
